import React, { forwardRef, useImperativeHandle, useState } from 'react';

import { CalendarIcon } from '@dynatrace/strato-icons';

import type { DateSelectorProps, DateSelectorRef } from './types.js';
import { Button } from '../../buttons/button/Button.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { useOverlayWithTrigger } from '../../overlays/hooks/useOverlayWithTrigger.js';
import { Overlay } from '../../overlays/overlay/Overlay.js';
import { globalSprinkles } from '../../styles/safe-sprinkles.js';
import { _Calendar as Calendar } from '../date-picker/calendar/Calendar.js';

/**
 * Calendar widget trigger and overlay component.
 */
export const DateSelector = forwardRef<DateSelectorRef, DateSelectorProps>(
  (props, forwardedRef) => {
    const {
      value,
      onChange,
      disabled,
      error,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    } = props;
    const [open, setOpen] = useState(false);

    const {
      targetRef,
      triggerRef,
      overlayRef,
      overlayState,
      overlayProps,
      overlayTriggerProps,
    } = useOverlayWithTrigger({
      placement: 'bottom-end',
      offset: 8,
      trapFocus: false,
      shouldCloseOnBlur: false,
      open,
      onOpenChange: setOpen,
      disabled,
    });

    const rootRef = useMergeRefs([triggerRef, targetRef]);

    useImperativeHandle(
      forwardedRef,
      () => ({
        open: () => setOpen(true),
        close: () => setOpen(false),
      }),
      [],
    );

    return (
      <>
        <Button
          ref={rootRef}
          data-testid={dataTestId}
          className={consumerClassName}
          style={consumerStyle}
          {...remainingProps}
          {...overlayTriggerProps}
          size="condensed"
          color={error ? 'critical' : 'neutral'}
        >
          <Button.Prefix>
            <CalendarIcon />
          </Button.Prefix>
        </Button>
        <Overlay
          ref={overlayRef}
          isOpen={overlayState.isOpen}
          className={globalSprinkles({
            paddingLeft: 16,
            paddingTop: 16,
            paddingRight: 16,
            paddingBottom: 16,
          })}
          overlayProps={overlayProps}
        >
          <Calendar
            value={value}
            onChange={(newIsoDate) => {
              if (newIsoDate) {
                overlayState.close();
                return onChange(newIsoDate);
              }
            }}
          />
        </Overlay>
      </>
    );
  },
);
